/** Les cles proposables dans le selecteur de la page Catalogue, triees. */
export const ART_KEYS: string[] = Object.keys(PRODUCT_ART).sort();
export const ICON_KEYS: string[] = Object.keys(CATEGORY_ICONS).sort();

/**
 * Le visuel d'un article: le sien, sinon l'icone de son rayon, sinon `box`.
 *
 * Rend AUSSI la nature du visuel, parce que `.tvis.art` et `.tvis.icon` ne se dessinent pas pareil
 * (72px en couleur contre 36px en trait teinte): choisir le dessin sans choisir sa classe donnerait
 * une illustration minuscule ou une icone geante.
 */
export function visualFor(
  artKey: string | null | undefined,
  categoryIcon: string | null | undefined,
): { svg: string; kind: "art" | "icon" } {
  if (artKey && PRODUCT_ART[artKey]) return { svg: PRODUCT_ART[artKey], kind: "art" };
  if (categoryIcon && CATEGORY_ICONS[categoryIcon]) {
    return { svg: CATEGORY_ICONS[categoryIcon], kind: "icon" };
  }
  return { svg: CATEGORY_ICONS.box ?? "", kind: "icon" };
}
